<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { app } from '../state.svelte';
  import { musicTime } from '../music.svelte';
  import { asError } from '../api/core';
  import { bytes } from '../format';
  import type { MediaAsset, MediaCollection, MediaDisc } from '../api/contracts';
  import MediaVideo from './MediaVideo.svelte';
  import Icon from './Icon.svelte';
  let { gameKey='',gameTitle='',library=false }:{gameKey?:string;gameTitle?:string;library?:boolean}=$props();
  let collections=$state<MediaCollection[]>([]);let all=$state<MediaCollection[]>([]);let collectionId=$state('');
  let title=$state('');let creating=$state(false);let existing=$state('');let busy=$state(false);let error=$state('');let note=$state('');
  let positions=$state<Record<string,number>>({});let selected=$state<MediaAsset|null>(null);let urls=$state<Record<string,string>>({});let reveal=$state(false);let filter=$state('all');let disc=$state<MediaDisc|null>(null);
  let stage=$state<HTMLDivElement>();let disposed=false;let editing=$state<MediaAsset|null>(null);let editTitle=$state('');let editSpoiler=$state(true);
  const current=$derived(collections.find(c=>c.id===collectionId)??collections[0]);
  const assets=$derived((current?.assets??[]).filter(a=>filter==='all'||a.kind===filter));
  const unlinked=$derived(all.filter(c=>!collections.some(link=>link.id===c.id)));
  async function refresh() {
    const list=await app.api.mediaCollections(library?undefined:gameKey);if(disposed)return;collections=list;
    all=library?list:await app.api.mediaCollections();
    const needed=list.flatMap(c=>c.assets).filter(a=>a.available&&!urls[a.id]);
    const resolved=await Promise.all(needed.map(async a=>[a.id,await app.api.mediaUrl(a.id)] as const));
    if(!disposed)urls={...urls,...Object.fromEntries(resolved)};
  }
  async function run(action:()=>Promise<unknown>) {if(busy)return;busy=true;error='';note='';try{await action();}catch(e){error=asError(e).message;}finally{try{await refresh();}catch(e){if(!error)error=asError(e).message;}busy=false;}}
  onMount(()=>{void run(async()=>{});});
  onDestroy(()=>{disposed=true;});
  function choose(asset:MediaAsset) {selected={...asset,position:positions[asset.id]??asset.position};error='';}
  function chooseCollection(id:string){selected=null;collectionId=id;reveal=false;disc=null;}
  $effect(()=>{if(!reveal&&selected?.spoiler)selected=null;});
  function edit(asset:MediaAsset){editing=asset;editTitle=asset.title;editSpoiler=asset.spoiler;}
  async function saveEdit(event:SubmitEvent){event.preventDefault();if(!editing)return;const id=editing.id;await run(async()=>{await app.api.mediaUpdate(id,editTitle,editSpoiler);if(selected?.id===id)selected={...selected,title:editTitle,spoiler:editSpoiler};editing=null;});}
  async function create(event:SubmitEvent){event.preventDefault();await run(async()=>{collectionId=await app.api.mediaCreate(title,library?undefined:gameKey);title='';creating=false;});}
  async function add(){if(!current)return;const id=current.id;await run(async()=>{const paths=await app.api.pickMedia();if(paths.length)await app.api.mediaImport(id,paths);});}
  async function inspect(){await run(async()=>{const path=await app.api.pickMediaDisc();if(path){disc=await app.api.mediaInspectDisc(path);note=`Found ${disc.items.length} images and videos. Choose only the extras you want to copy.`;}});}
  async function importDisc(member:string){if(!disc||!current)return;const d=disc;const id=current.id;await run(async()=>{await app.api.mediaImportDisc(id,d.path,d.signature,member);note='Selected media added. The original disc image is unchanged.';});}
  async function fullscreen(){if(!stage)return;try{if(document.fullscreenElement)await document.exitFullscreen();else await stage.requestFullscreen();}catch{error='Fullscreen is unavailable in this window.';}}
  function move(offset:number){if(!selected)return;const images=assets.filter(a=>a.kind==='image'&&a.available);const i=images.findIndex(a=>a.id===selected?.id);if(images.length)void choose(images[(i+offset+images.length)%images.length]);}
</script>

<section class="media-library" aria-label={library?'Media library':'Game media library'}>
  <header><div><span class="eyebrow">{library?'YOUR COLLECTION':'GAME EXTRAS'}</span><h2>Media</h2><p>Artwork, bonus features and moments worth keeping.</p></div><button class="btn glass small" data-nav disabled={busy} onclick={()=>{title=library?'':`${gameTitle} — Extras`;creating=!creating;}}><Icon name="plus" size={16}/>New collection</button></header>
  {#if error}<p class="error" role="alert">{error}</p>{/if}{#if note}<p class="note" role="status">{note}</p>{/if}{#if busy}<p role="status" class="note">Working… Selected videos may take a moment to copy.</p>{/if}
  {#if creating}<form class="glass-panel editor" onsubmit={create}><label>Collection title<input data-nav bind:value={title} maxlength="300" required placeholder="Game title — Extras"/></label><button class="btn primary small" data-nav disabled={busy||!title.trim()}>Create collection</button></form>{/if}
  {#if !library&&unlinked.length}<form class="link" onsubmit={e=>{e.preventDefault();void run(()=>app.api.mediaLink(existing,gameKey,true));}}><label>Link an existing collection<select data-nav bind:value={existing}><option value="">Choose collection</option>{#each unlinked as c}<option value={c.id}>{c.title}</option>{/each}</select></label><button class="btn glass small" data-nav disabled={busy||!existing}>Link</button></form>{/if}
  {#if collections.length}<div class="collection-tabs" aria-label="Media collections">{#each collections as c}<button class:active={current?.id===c.id} aria-pressed={current?.id===c.id} data-nav onclick={()=>chooseCollection(c.id)}>{c.title}<span>{c.assets.length}</span></button>{/each}</div>{/if}
  {#if current}
    <div class="collection-head"><h3>{current.title}</h3><div class="actions"><button class="btn glass small" data-nav disabled={busy} onclick={add}><Icon name="plus" size={16}/>Add files</button><button class="btn glass small" data-nav disabled={busy} onclick={inspect}><Icon name="folder" size={16}/>Browse disc</button>{#if !library}<button class="btn glass small" data-nav disabled={busy} title="Collection stays in Media" onclick={()=>run(()=>app.api.mediaLink(current!.id,gameKey,false))}>Unlink</button>{/if}</div></div>
    {#if selected}
      <div class="viewer glass-panel" bind:this={stage}>
        <div class="viewer-head"><div><span class="eyebrow">{selected.kind==='video'?'NOW WATCHING':'GALLERY'}</span><h3>{selected.title}</h3></div><div class="actions">{#if selected.kind==='image'}<button class="icon" data-nav aria-label="Previous image" onclick={()=>move(-1)}><Icon name="previous" size={18}/></button><button class="icon" data-nav aria-label="Next image" onclick={()=>move(1)}><Icon name="next" size={18}/></button>{/if}<button class="icon" data-nav aria-label="Fullscreen media" onclick={fullscreen}><Icon name="tv" size={18}/></button><button class="icon" data-nav aria-label="Close media" onclick={()=>{selected=null;}}><Icon name="x" size={18}/></button></div></div>
        {#key selected.id}
          {#if selected.kind==='video'}
            <MediaVideo asset={selected} url={urls[selected.id]} onposition={(id,position)=>positions={...positions,[id]:position}} onerror={()=>error='This video could not play. Its codec may need conversion to H.264/AAC MP4 or WebM.'}/>

          {:else}<img class="full-image" src={urls[selected.id]} alt={selected.title}/>{/if}
        {/key}
        <p class="credit">{selected.kind==='video'?'Playback position is remembered. ':''}Local collection · {bytes(selected.bytes)}</p>
      </div>
    {/if}
    <div class="filters"><div>{#each [['all','All'],['video','Videos'],['image','Gallery']] as [value,label]}<button data-nav class:active={filter===value} aria-pressed={filter===value} onclick={()=>filter=value}>{label}</button>{/each}</div><label class="reveal"><input type="checkbox" data-nav bind:checked={reveal}/>Reveal videos · may contain spoilers</label></div>
    {#if editing}<form class="editor glass-panel" onsubmit={saveEdit}><label>Media title<input data-nav required bind:value={editTitle} maxlength="300"/></label><label class="reveal"><input type="checkbox" data-nav bind:checked={editSpoiler}/>Contains spoilers</label><button class="btn primary small" data-nav disabled={busy}>Save details</button><button type="button" class="btn glass small" data-nav onclick={()=>editing=null}>Cancel</button></form>{/if}
    {#if assets.length}<div class="asset-grid">{#each assets as asset (asset.id)}
      <article class="asset" class:selected={selected?.id===asset.id}>
        <button class="thumbnail" data-nav disabled={!asset.available||(asset.spoiler&&!reveal)} onclick={()=>choose(asset)} aria-label={asset.spoiler&&!reveal?'Hidden video':`Open ${asset.title}`}>
          {#if asset.kind==='image'&&urls[asset.id]}<img src={urls[asset.id]} alt="" loading="lazy"/>{:else}<div class="video-placeholder"><Icon name="play" size={32}/><span>{asset.spoiler&&!reveal?'Reveal videos to watch':(positions[asset.id]??asset.position)>0?`Resume · ${musicTime(positions[asset.id]??asset.position)}`:'Video'}</span></div>{/if}
        </button><div class="asset-caption"><div><strong>{asset.spoiler&&!reveal?'Hidden video':asset.title}</strong><span>{asset.available?`${asset.kind==='image'?'Image':'Video'} · ${bytes(asset.bytes)}`:'File unavailable'}</span></div><button class="icon" data-nav disabled={asset.spoiler&&!reveal} aria-label="Edit media details" onclick={()=>edit(asset)}><Icon name="edit" size={14}/></button><button class="icon remove" data-nav disabled={busy} aria-label="Remove media from collection" title="Remove from collection; original files are kept" onclick={()=>run(async()=>{if(selected?.id===asset.id){selected=null;}await app.api.mediaRemove(asset.id);})}><Icon name="x" size={14}/></button></div>
      </article>
    {/each}</div>{:else}<div class="empty glass-panel"><Icon name="image" size={36}/><h3>{filter==='all'?'Build this collection':'No matching media'}</h3><p>Add local images and MP4/WebM videos, or browse a disc and copy selected extras.</p></div>{/if}
    {#if disc}<section class="disc glass-panel"><div class="collection-head"><div><h3>Disc extras</h3><p>{disc.items.length} candidates · {bytes(disc.source_bytes)} image</p></div><button class="btn glass small" data-nav onclick={()=>disc=null}>Close browser</button></div><p>Directory inspection only. Import copies one selected item. Raw M2V cinematics need conversion; audio pairing is not implemented.</p><ul>{#each disc.items as item}<li><div><strong>{item.path.split('/').pop()}</strong><small>{item.path} · {bytes(item.bytes)}</small></div><button class="btn glass small" data-nav disabled={busy||!item.supported||item.bytes>2*1024*1024*1024} onclick={()=>importDisc(item.path)}>{!item.supported?'Needs conversion':item.bytes>2*1024*1024*1024?'Over 2 GiB':'Add to collection'}</button></li>{/each}</ul></section>{/if}
  {:else if !creating}<div class="empty glass-panel"><Icon name="image" size={40}/><h3>A place for your game extras</h3><p>Create a collection for artwork, trailers and bonus features. Collections can be linked to games later.</p></div>{/if}
</section>

<style>
  .media-library{padding:24px var(--gutter);max-width:1240px;margin:0 auto;display:grid;gap:22px;min-width:0}header,.collection-head,.viewer-head{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h2{font-size:30px;margin:6px 0}h3{margin:0;font-size:18px}p{color:var(--text-soft);font-size:13px;line-height:1.6;margin:6px 0}.eyebrow{font-size:10px;letter-spacing:.12em;color:var(--text-dim)}.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.editor,.link{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.editor{padding:18px}.editor label,.link label{display:grid;gap:6px;font-size:12px;min-width:0;flex:1}.editor input:not([type=checkbox]),.link select{width:100%;min-width:0;box-sizing:border-box}input:not([type=checkbox]),select{color:var(--text);background:var(--field);border:1px solid var(--line);padding:10px;border-radius:8px;min-width:230px}.collection-tabs,.filters,.filters>div{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.collection-tabs button,.filters button{border:1px solid var(--line);background:var(--field);color:var(--text-soft);padding:9px 13px;border-radius:8px;cursor:pointer;font:inherit;font-size:12px}.collection-tabs .active,.filters .active{color:var(--text);border-color:var(--accent);background:var(--field-strong)}.collection-tabs span{margin-left:12px;color:var(--text-dim)}.filters{justify-content:space-between}.reveal{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--text-soft)}.asset-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:22px}.asset{min-width:0}.thumbnail{width:100%;aspect-ratio:16/10;background:var(--field);border:1px solid var(--line);border-radius:10px;overflow:hidden;padding:0;cursor:pointer;color:var(--text-soft)}.thumbnail:hover:not(:disabled),.selected .thumbnail{border-color:var(--accent)}.thumbnail:disabled{cursor:default}.thumbnail img{width:100%;height:100%;object-fit:contain;display:block}.video-placeholder{display:grid;place-content:center;justify-items:center;gap:14px;height:100%;background:radial-gradient(ellipse at top right,color-mix(in srgb,var(--accent) 18%,transparent),transparent 75%)}.video-placeholder span{font-size:11px}.asset-caption{display:flex;justify-content:space-between;gap:8px;margin-top:10px}.asset-caption>div{min-width:0;display:grid;gap:5px}.asset-caption strong{font-size:13px;overflow-wrap:anywhere}.asset-caption span,.credit{font-size:11px;color:var(--text-dim)}.icon{display:grid;place-items:center;width:32px;height:32px;border:1px solid var(--line);border-radius:7px;background:var(--field);color:var(--text-soft);cursor:pointer;flex-shrink:0}.remove{opacity:.55}.remove:hover{opacity:1}.viewer{padding:16px;border-radius:12px;overflow:hidden}.viewer-head{margin-bottom:14px}.full-image{display:block;width:100%;max-height:65vh;object-fit:contain;background:#06080c;border-radius:6px}.credit{margin-top:12px}.viewer:fullscreen{display:flex;flex-direction:column;background:#080a10;box-sizing:border-box}.viewer:fullscreen .full-image{flex:1;min-height:0;max-height:none}.empty{padding:45px 24px;text-align:center;border-radius:12px}.empty> :global(svg){margin-bottom:15px;color:var(--text-dim)}.error{color:var(--danger)}.note{color:var(--text-soft)}.disc{padding:20px;border-radius:12px;min-width:0}.disc ul{list-style:none;padding:0;max-height:480px;overflow:auto}.disc li{display:flex;align-items:center;justify-content:space-between;gap:15px;border-top:1px solid var(--line);padding:12px 0}.disc li>div{display:grid;gap:5px;min-width:0}.disc strong{font-size:12px;overflow-wrap:anywhere}.disc small{color:var(--text-dim);font-size:11px;overflow-wrap:anywhere}.disc li button{flex-shrink:0}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:640px){.asset-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.disc li{align-items:start;flex-direction:column}.media-library{padding:18px var(--gutter)}}
</style>
